last_hashtags_text":null,"backblast_intro_text":"","backblast_posted_at":null,"backblast_status":null,"backblast_text":"","created_at":1788436800000,"created_by_user_id":"a2072e94-56ee-447c-aeb3-e820e1fc4c4d","date":"2026-09-03","fngs":[],"id":"b35f9e2c-4cd4-5e86-94d1-ff9d6398b50b","notes":null,"q_id":"ac159b62-ae95-5729-9cbc-43fcc690c528","q_ids":["ac159b62-ae95-5729-9cbc-43fcc690c528"],"region_id":"45a32e90-3f95-5261-bb49-5719f6f77cca","site_id":"036d7123-ccd1-5de1-9f51-d959d7644840","source_planned_workout_id":null,"source_q_slot_id":null,"start_time":"05:15","unresolved_pax":[],"weather_snapshot":null,"workout":null},{"announcement_snapshot":{"materializedAt":"2026-09-28T22:31:22.923Z","source":"workout_execution","text":"HHR"},"announcement_text":"HHR","ao_id":"c40e2d58-7774-59f2-b55a-9637d689a019","ao_name":"The Ruff","attendance_review_notes":null,"attendance_review_status":"not_required","attendee_ids":["ba6f2fd9-66dd-4e63-bd65-bcf8a59af514","fc85ffc1-ad5a-5248-bcfd-19d82e3fe80b"],"backblast_body_text":"Title: The Longest Mile\n\nIntroduction:\nPlease refer to the preamble:\nf3sactown.com/qrg\n\nWarm-O-Rama:\nSquats 15x IC\n\nThangs:\nThang 1\nAbyss Merkin\nAbyss Merkin Perform merkins on two parallel benches, right hand and foot on one bench, and left hand and foot on the other bench, letting your body lower into the space between the benches as far a possible. Works best if done slowly, holding at the lowest point and imagining a bottomless abyss below you.\nMay also be performed between two coupons. Pax line up and place coupons on ground then shift 1/2 a position so that pax are in the “window” of two coupons. Each pax places his left hand on the coupon to his left, his right hand on the coupon to his right. Perform merkins into the abyss. The number of coupons should be the number of pax +1 to allow each pax the opportunity stare into the unblinking abyss.\n\nMary / Finisher:\nBlimps\n5 burpees, 10 lunge each leg, 15 imperial walker, 20 merkins, 25 plank jacks, 30 squats. Rinse and repeat as needed. Can be done to cross a field or lot.\n\nANNOUNCEMENTS\n\nHHR","backblast_hashtags_text":null,"backblast_intro_text":null,"backblast_posted_at":"2026-09-28T22:31:38.948+00:00","backblast_status":"shared","backblast_text":"#backblast #TheRuff\n\n1 HIM met at The Ruff today to get 1% better.\n\nThe Ruff · Mon, Sep 28, 2026\nSouthport Levee Trailhead\n\nTotal Attendees: 1\n\nQ: @Casper\n\nPAX (0):\nNone\n\nVisiting PAX (0):\nNone\n\nFNGs (0):\nNone\n\nTitle: The Longest Mile\n\nIntroduction:\nPlease refer to the preamble:\nf3sactown.com/qrg\n\nWarm-O-Rama:\nSquats 15x IC\n\nThangs:\nThang 1\nAbyss Merkin\nAbyss Merkin Perform merkins on two parallel benches, right hand and foot on one bench, and left hand and foot on the other bench, letting your body lower into the space between the benches as far a possible. Works best if done slowly, holding at the lowest point and imagining a bottomless abyss below you.\nMay also be performed between two coupons. Pax line up and place coupons on ground then shift 1/2 a position so that pax are in the “window” of two coupons. Each pax places his left hand on the coupon to his left, his right hand on the coupon to his right. Perform merkins into the abyss. The number of coupons should be the number of pax +1 to allow each pax the opportunity stare into the unblinking abyss.\n\nMary / Finisher:\nBlimps\n5 burpees, 10 lunge each leg, 15 imperial walker, 20 merkins, 25 plank jacks, 30 squats. Rinse and repeat as needed. Can be done to cross a field or lot.\n\nANNOUNCEMENTS\n\nHHR","created_at":1790634662391,"created_by_user_id":"e3960100-32c6-40c2-935c-ead578380bcd","date":"2026-09-28","fngs":[{"invitedById":"fc85ffc1-ad5a-5248-bcfd-19d82e3fe80b","inviterIds":["fc85ffc1-ad5a-5248-bcfd-19d82e3fe80b"],"memberId":"ba6f2fd9-66dd-4e63-bd65-bcf8a59af514","paxName":"Yoyo","realName":"Joe Smith"}],"id":"b5b1d095-128d-40e0-921b-7bfb83e366ff","notes":"","q_id":"fc85ffc1-ad5a-5248-bcfd-19d82e3fe80b","