text":"","created_at":1789041600000,"created_by_user_id":"a2072e94-56ee-447c-aeb3-e820e1fc4c4d","date":"2026-09-10","fngs":[],"id":"f87d180c-49f6-53e9-8deb-ec70bf46f190","notes":null,"q_id":"fc85ffc1-ad5a-5248-bcfd-19d82e3fe80b","q_ids":["fc85ffc1-ad5a-5248-bcfd-19d82e3fe80b"],"region_id":"45a32e90-3f95-5261-bb49-5719f6f77cca","site_id":"063851f0-8547-5a23-8f0d-d2541d0c55ed","source_planned_workout_id":null,"source_q_slot_id":null,"start_time":"19:00","unresolved_pax":[],"weather_snapshot":null,"workout":null},{"announcement_snapshot":null,"announcement_text":null,"ao_id":"d8aa4d2b-a3b9-55ad-8045-b278236c905d","ao_name":"Terminus","attendance_review_notes":null,"attendance_review_status":"not_required","attendee_ids":["d3804c86-71c5-5ed0-b93a-b942f4575761","d1a0f09a-19b1-5a7e-8ba3-b08907f5d543","e92bd682-db66-5170-802b-201bf41e6971","c767867e-54fa-561f-bb2a-4318ceb3937e","4abd3148-10c4-54a2-a80c-e9523ea3321d"],"backblast_body_text":"","backblast_hashtags_text":null,"backblast_intro_text":"","backblast_posted_at":null,"backblast_status":null,"backblast_text":"","created_at":1789041600000,"created_by_user_id":"a2072e94-56ee-447c-aeb3-e820e1fc4c4d","date":"2026-09-10","fngs":[],"id":"f9765456-7148-5527-b133-0bf418d098d6","notes":null,"q_id":"d3804c86-71c5-5ed0-b93a-b942f4575761","q_ids":["d3804c86-71c5-5ed0-b93a-b942f4575761"],"region_id":"45a32e90-3f95-5261-bb49-5719f6f77cca","site_id":"036d7123-ccd1-5de1-9f51-d959d7644840","source_planned_workout_id":null,"source_q_slot_id":null,"start_time":"05:15","unresolved_pax":[],"weather_snapshot":null,"workout":null},{"announcement_snapshot":{"materializedAt":"2026-10-01T23:55:13.522Z","source":"workout_execution","text":""},"announcement_text":"","ao_id":"d8aa4d2b-a3b9-55ad-8045-b278236c905d","ao_name":"Terminus","attendance_review_notes":null,"attendance_review_status":"not_required","attendee_ids":["11633fcc-2a5f-50b4-915e-2dc6b4025bf8","34a93543-363f-5798-abd0-61828ec99d36","68dc02ea-3180-59e0-90a7-c5b61ac41247","7b32656c-e5c8-50da-93a0-743833514dc0","c923a3f3-9519-451e-948f-b004abf6e020","d1a0f09a-19b1-5a7e-8ba3-b08907f5d543","d3804c86-71c5-5ed0-b93a-b942f4575761","e92bd682-db66-5170-802b-201bf41e6971","fc85ffc1-ad5a-5248-bcfd-19d82e3fe80b"],"backblast_body_text":"Title: Fobulous Q\n\nIntroduction:\nWelcome to F3 – stands for Fitness, Fellowship, and Faith\nOur mission is to plant, grow and serve small workout groups for men, for the invigoration\nof male community leadership.\nWe have five core principles:\n1. Free of charge,\n2. Open to all men,\n3. Held outdoors rain or shine,\n4. Led in rotating fashion by one of your peers,\n5. Ends in circle of trust\nDisclaimer- I am not a professional so modify if necessary, to prevent injury, but not to\nprevent growth.\nOur motto is- leave no man behind but leave no man where you found him.\n\nWarm-O-Rama:\nLittle arm circles forward (10) little arm circles backward (10), in cadence\n\nThangs:\nThang 1\nSit down Touch toes 30 secs\nAmerican hammers 45 secs\nLittle Baby Flutter Crunches (On your 6, feet do flutter kick while upper body does crunch.\nIgnore number of times your legs move, only count crunches) 30 secs\nSquats 30 secs\nJog to the dock: 5 Alligator merkins and jog to the end, then 10 alligator merkins and jog to\nthe end. 15 alligator merkins and jog to the middle.\nWalking lunges (5, 10, 15) along with incline merkins (5, 10, 15), 5 burpees. \nFor those finish early, do 15 of imperial walkers. Everyone do imperial walkers together for\n30 seconds.\nRun to the Holiday Inn hotel –\nSideway bear crawl on the stairs, walk back down and repeat with using the other side of the body. Let’s do this for four times. Two\non each side.\nThen jog back to the starting point,\n\nMary / Finisher:\nmerry go around.\n\nNotes:\nThank you all for coming!","backblast_hashtags_text":null,"backblast_intro_text":null,"backblast_posted_at":null,"backblast_status":null,"backblast_text":"#backblast #Terminus\n\n9 HIM met at Terminus today to get 1% better.\n\nTerminus · Thu, Oct 1, 2026\nRailroad Museum\n\nTotal Attendees: 9\n\nQ: @Casper\n\nPAX (7):\n@Bullwinkle\n@Carter\n@Carville\n@Fancy\n@Fobulous\n@Husky\n@Mr. Burns\n\nVisiting PAX (0):\nNone\n\nFNGs (1):\nLoincloth\n\nTitle: Fobulous Q\n\nIntroduction:\nWelcome to F3 – stands for Fitness, Fellowship, and Faith\nOur mission is to plant, grow and serve small workout groups for men, for the invigoration\nof male community leadership.\nWe have five core principles:\n1. Free of charge,\n2. Open to all men,\n3. Held outdoors rain or shine,\n4. Led in rotating fashion by one of your peers,\n5. Ends in circle of trust\nDisclaimer- I am not a professional so modify if necessary, to prevent injury, but not to\nprevent growth.\nOur motto is- leave no man behind but leave no man where you found him.\n\nWarm-O-Rama:\nLittle arm circles forward (10) little arm circles backward (10), in cadence\n\nThangs:\nThang 1\nSit down Touch toes 30 secs\nAmerican hammers 45 secs\nLittle Baby Flutter Crunches (On your 6, feet do flutter kick while upper body does crunch.\nIgnore number of times your legs move, only count crunches) 30 secs\nSquats 30 secs\nJog to the dock: 5 Alligator merkins and jog to the end, then 10 alligator merkins and jog to\nthe end. 15 alligator merkins and jog to the middle.\nWalking lunges (5, 10, 15) along with incline merkins (5, 10, 15), 5 burpees. \nFor those finish early, do 15 of imperial walkers. Everyone do imperial walkers together for\n30 seconds.\nRun to the Holiday Inn hotel –\nSideway bear crawl on the stairs, walk back down and repeat with using the other side of the body. Let’s do this for four times. Two\non each side.\nThen jog back to the starting point,\n\nMary / Finisher:\nmerry go around.\n\nNotes:\nThank you all for coming!","created_at":1790898773519,"created_by_user_id":"e3960100-32c6-40c2-935c-ead578380bcd","date":"2026-10-01","fngs":[{"invitedById":null,"inviterIds":[],"memberId":"c923a3f3-9519-451e-948f-b004abf6e020","paxName":"L