do $preflight$
declare p jsonb := (select document from st_payload); c jsonb := p->'contract';
begin
  if c->>'schemaVersion'<>'sactown-2026-ytd-region-local-v1' or c->>'sourceManifestSha256'<>'15d602e8988643934032c497239cdcc2a9b027ef1b199358426b44997b0a11e2' then raise exception 'Source manifest/package contract mismatch'; end if;
  if c->>'regionId'<>'45a32e90-3f95-5261-bb49-5719f6f77cca' or c->>'projectId'<>'6a9fade6-aeda-5fcf-a383-30278385f3b6' or c->>'batchId'<>'76ba6b0d-b12a-5de4-b1f4-716e4a828b44' or c->>'windowStart'<>'2026-01-01' or c->>'windowEnd'<>'2026-08-30' then raise exception 'Target IDs or historical window changed'; end if;
  if jsonb_array_length(p->'members')<>252 or (select count(*) from jsonb_array_elements(p->'members') m where m->>'action'='reuse_seed')<>64 or (select count(*) from jsonb_array_elements(p->'members') m where m->>'action'='create')<>188 then raise exception 'Approved region-local identity partition changed'; end if;
  if (select count(distinct m->>'memberId') from jsonb_array_elements(p->'members') m)<>252 or (select count(distinct m->>'sourceIdentityKey') from jsonb_array_elements(p->'members') m)<>252 or (select count(distinct m->>'sourceIdentityId') from jsonb_array_elements(p->'members') m)<>252 or (select count(distinct m->>'resolutionId') from jsonb_array_elements(p->'members') m)<>252 then raise exception 'Deterministic identity IDs or source keys are not unique'; end if;
  if jsonb_array_length(p->'sessions')<>540 or (select count(distinct e->>'sessionId') from jsonb_array_elements(p->'sessions') e)<>540 or (select count(distinct concat_ws('|',e->>'date',e->>'aoId',e->>'startTime')) from jsonb_array_elements(p->'sessions') e)<>540 then raise exception 'Deterministic session IDs or business keys changed'; end if;
  if (select coalesce(sum(jsonb_array_length(e->'attendeeIds')),0) from jsonb_array_elements(p->'sessions') e)<>4436 or (select coalesce(sum(jsonb_array_length(e->'qIds')),0) from jsonb_array_elements(p->'sessions') e)<>564 or (select coalesce(sum(jsonb_array_length(e->'fngs')),0) from jsonb_array_elements(p->'sessions') e)<>134 then raise exception 'Embedded relationship totals changed'; end if;
  if exists(select 1 from jsonb_array_elements(p->'sessions') e where e->>'date'<'2026-01-01' or e->>'date'>'2026-08-30') then raise exception 'Embedded session falls outside the approved window'; end if;
  if not exists(select 1 from public.profiles where id='a2072e94-56ee-447c-aeb3-e820e1fc4c4d'::uuid and role='superadmin') then raise exception 'Approved superadmin profile missing'; end if;
  if not exists(select 1 from public.regions where id='45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid and name='F3 SacTown Demo' and slug='sactown-demo' and environment='production' and lifecycle_status='onboarding' and include_in_reporting=false and activated_at is null and timezone='America/Los_Angeles') then raise exception 'SacTown lifecycle/environment contract mismatch'; end if;
  if (select count(*) from public.members where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>71 or (select count(*) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>40 or (select count(*) from public.aos where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>18 or (select count(*) from public.sites where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>12 or (select count(*) from public.ao_recurring_schedules where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>18 then raise exception 'SacTown baseline record counts changed'; end if;
  if (select coalesce(sum(jsonb_array_length(coalesce(attendee_ids,'[]'::jsonb))),0) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>286 or (select coalesce(sum(cardinality(coalesce(q_ids,'{}'::uuid[]))),0) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>40 or (select coalesce(sum(jsonb_array_length(coalesce(fngs,'[]'::jsonb))),0) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>7 then raise exception 'SacTown baseline relationship counts changed'; end if;
  if exists(select 1 from jsonb_array_elements(p#>'{baseline,protectedSessions}') e left join public.sessions s on s.id=(e->>'id')::uuid where s.id is null or to_jsonb(s) is distinct from e) or (select count(*) from jsonb_array_elements(p#>'{baseline,protectedSessions}'))<>40 then raise exception 'A protected SacTown session changed or is missing'; end if;
  if exists(select 1 from jsonb_array_elements(p->'members') m left join public.members x on x.id=(m->>'memberId')::uuid where m->>'action'='reuse_seed' and (x.id is null or x.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid or x.pax_name is distinct from m->>'sourceIdentity' or x.status<>'active')) then raise exception 'A reused SacTown seed identity is unresolved or changed'; end if;
  if exists(select 1 from jsonb_array_elements(p->'members') m join public.members x on x.id=(m->>'memberId')::uuid where m->>'action'='create') then raise exception 'A planned new member ID already exists'; end if;
  if exists(select 1 from jsonb_array_elements(p->'members') m join public.members x on x.region_id='45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid and lower(btrim(x.pax_name))=lower(btrim(m->>'sourceIdentity')) where m->>'action'='create') then raise exception 'A planned new source identity now collides with an existing SacTown name'; end if;
  if exists(
    select 1
    from jsonb_array_elements(p->'sessions') e
    cross join lateral (
      select value member_id from jsonb_array_elements_text(e->'attendeeIds')
      union all select value from jsonb_array_elements_text(e->'qIds')
      union all select f->>'memberId' from jsonb_array_elements(e->'fngs') f
      union all select f->>'invitedById' from jsonb_array_elements(e->'fngs') f where nullif(f->>'invitedById','') is not null
      union all select value from jsonb_array_elements(e->'fngs') f cross join lateral jsonb_array_elements_text(coalesce(f->'inviterIds','[]'::jsonb))
    ) referenced
    where not exists(select 1 from jsonb_array_elements(p->'members') m where m->>'memberId'=referenced.member_id)
  ) then raise exception 'An imported session references a member outside the approved 252 SacTown-local identities'; end if;
  if exists(select 1 from jsonb_array_elements(p->'members') m join public.members x on x.id=(m->>'memberId')::uuid where x.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid) then raise exception 'An imported identity resolves to an external-region canonical member'; end if;
  if exists(select 1 from jsonb_array_elements(p->'members') m join public.region_participants rp on rp.member_id=(m->>'memberId')::uuid where m->>'action'='reuse_seed' and rp.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid)
     or exists(select 1 from jsonb_array_elements(p->'members') m join public.member_stats ms on ms.member_id=(m->>'memberId')::uuid where m->>'action'='reuse_seed' and ms.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid)
     or exists(select 1 from jsonb_array_elements(p->'members') m join public.sessions s on s.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid and (coalesce(s.attendee_ids,'[]'::jsonb) ? (m->>'memberId') or (m->>'memberId')::uuid=any(coalesce(s.q_ids,'{}'::uuid[])) or s.q_id=(m->>'memberId')::uuid or exists(select 1 from jsonb_array_elements(coalesce(s.fngs,'[]'::jsonb)) f where f->>'memberId'=m->>'memberId')) where m->>'action'='reuse_seed'
  then raise exception 'An approved reused SacTown seed identity already has cross-region activity'; end if;
  if exists(select 1 from jsonb_array_elements(p->'sessions') e join public.sessions s on s.id=(e->>'sessionId')::uuid) then raise exception 'A planned session ID already exists'; end if;
  if exists(select 1 from jsonb_array_elements(p->'sessions') e join public.sessions s on s.region_id='45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid and s.date=e->>'date' and s.ao_id=(e->>'aoId')::uuid and nullif(s.start_time,'') is not distinct from nullif(e->>'startTime','')) then raise exception 'A SacTown AO/date/time session collision exists'; end if;
  if exists(select 1 from public.region_import_projects where id='6a9fade6-aeda-5fcf-a383-30278385f3b6'::uuid) or exists(select 1 from public.region_import_batches where id='76ba6b0d-b12a-5de4-b1f4-716e4a828b44'::uuid) or exists(select 1 from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6'::uuid) then raise exception 'Extension project, batch, or ledger already exists'; end if;
  if exists(select 1 from jsonb_array_elements(p->'sessions') e left join public.aos a on a.id=(e->>'aoId')::uuid left join public.sites s on s.id=(e->>'siteId')::uuid where (e->>'aoName')<>'Rumble' and (a.id is null or a.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid or a.name is distinct from e->>'aoName' or s.id is null or s.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid)) then raise exception 'An AO/site reference is unresolved'; end if;
  if not exists(select 1 from public.sites where id=(p#>>'{rumble,siteId}')::uuid and region_id='45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid) or exists(select 1 from public.aos where id=(p#>>'{rumble,id}')::uuid or (region_id='45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid and (name=p#>>'{rumble,name}' or slug=p#>>'{rumble,slug}'))) or exists(select 1 from public.ao_recurring_schedules where id=(p#>>'{rumble,scheduleId}')::uuid) then raise exception 'Rumble site, name, slug, or deterministic IDs conflict'; end if;
end $preflight$;

