do $derived$ declare x record; begin
  for x in select (e->>'sessionId')::uuid id from st_payload p cross join lateral jsonb_array_elements(p.document->'sessions') e loop perform public.sync_region_participants_for_session(x.id); end loop;
  perform public.rebuild_member_stats_for_region('45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid);
end $derived$;

do $postflight$
declare p jsonb := (select document from st_payload); begin
  if (select count(*) from public.members where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>259 or (select count(*) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>580 or (select count(*) from public.aos where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>19 or (select count(*) from public.sites where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>12 or (select count(*) from public.ao_recurring_schedules where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>19 then raise exception 'Final SacTown record counts mismatch'; end if;
  if (select coalesce(sum(jsonb_array_length(coalesce(attendee_ids,'[]'::jsonb))),0) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>4722 or (select coalesce(sum(cardinality(coalesce(q_ids,'{}'::uuid[]))),0) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>604 or (select coalesce(sum(jsonb_array_length(coalesce(fngs,'[]'::jsonb))),0) from public.sessions where region_id='45a32e90-3f95-5261-bb49-5719f6f77cca')<>141 then raise exception 'Final SacTown relationship totals mismatch'; end if;
  if exists(select 1 from public.sactown_2026_ytd_extension_ledger l left join public.sessions s on s.id=l.target_id where l.project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and l.target_table='sessions' and l.operation='snapshot_before' and (s.id is null or to_jsonb(s) is distinct from l.row_snapshot)) or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='sessions' and operation='snapshot_before')<>40 then raise exception 'A protected baseline session changed or is missing'; end if;
  if (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='region_import_projects' and operation='inserted')<>1 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='region_import_batches' and operation='inserted')<>1 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='members' and operation='inserted')<>188 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='region_import_source_identities' and operation='inserted')<>252 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='region_import_identity_resolutions' and operation='inserted')<>252 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='aos' and operation='inserted')<>1 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='ao_recurring_schedules' and operation='inserted')<>1 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='sessions' and operation='inserted')<>540 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6' and target_table='merge_candidate' and operation='information')<>42 or (select count(*) from public.sactown_2026_ytd_extension_ledger where project_id='6a9fade6-aeda-5fcf-a383-30278385f3b6')<>1318 then raise exception 'Inserted-ID ledger reconciliation failed'; end if;
  if exists(select 1 from jsonb_array_elements(p->'members') m join public.members x on x.id=(m->>'memberId')::uuid where x.region_id<>'45a32e90-3f95-5261-bb49-5719f6f77cca'::uuid) then raise exception 'Post-import identity isolation failed'; end if;
  if not exists(select 1 from public.regions where id='45a32e90-3f95-5261-bb49-5719f6f77cca' and environment='production' and lifecycle_status='onboarding' and include_in_reporting=false and activated_at is null) then raise exception 'SacTown lifecycle changed'; end if;
